package com.orderflow.scheduler;
import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;
public class ConservativeRetentionJob{private final JdbcTemplate jdbc;private final PostgresJobScheduler scheduler;private final RetentionProperties properties;private final MeterRegistry metrics;private final Clock clock;public ConservativeRetentionJob(JdbcTemplate j,PostgresJobScheduler s,RetentionProperties p,MeterRegistry m,Clock c){jdbc=j;scheduler=s;properties=p;metrics=m;clock=c;}@Scheduled(fixedDelayString="${app.retention.delay:24h}",initialDelayString="${app.retention.delay:24h}")public void cleanup(){scheduler.execute("serviceRetentionJob",properties.lockDuration(),ignored->clean());}JobResult clean(){Instant now=Instant.now(clock);int count=0;if(exists("processed_event"))count+=delete("processed_event","processed_at < ?",now.minus(properties.processedEvent()));if(exists("idempotency_record"))count+=delete("idempotency_record","completed_at IS NOT NULL AND completed_at < ?",now.minus(properties.idempotency()));if(exists("outbox_event"))count+=delete("outbox_event","status='PUBLISHED' AND published_at < ?",now.minus(properties.publishedOutbox()));count+=delete("scheduled_job_run","status <> 'RUNNING' AND completed_at < ?",now.minus(properties.jobHistory()));metrics.counter("retention_cleanup_records_total").increment(count);return JobResult.success(count);}private boolean exists(String table){Boolean value=jdbc.queryForObject("SELECT to_regclass(?) IS NOT NULL",Boolean.class,table);return Boolean.TRUE.equals(value);}private int delete(String table,String predicate,Instant cutoff){return jdbc.update("DELETE FROM "+table+" WHERE ctid IN (SELECT ctid FROM "+table+" WHERE "+predicate+" LIMIT ?)",cutoff,properties.batchSize());}}
